const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7'); // You must include this line

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const roi = ee.Geometry.Point([-73.7781, 40.6413]).buffer(3000); // JFK approx, 3 km buffer
    const scale = 10000; // ~10 km, appropriate for ERA5-Land (~9km)
    const dayStart = '2025-06-24';
    const dayEnd = '2025-06-25';
    const histStart = '2020-01-01';
    const histEnd = '2024-12-31';

    // Helper to pick a dataset with data
    function pickWithData(ids, filterFn) {
      for (let i = 0; i < ids.length; i++) {
        const col = filterFn(ee.ImageCollection(ids[i]));
        const sz = col.size().getInfo();
        if (sz > 0) return {id: ids[i], col: col, size: sz};
      }
      return {id: null, col: null, size: 0};
    }

    // 2. Data Acquisition & Check
    const candidates = ['ECMWF/ERA5_LAND/HOURLY', 'ECMWF/ERA5/HOURLY'];

    // Day 2025-06-24
    const dayPick = pickWithData(candidates, (c) =>
      c.filterDate(dayStart, dayEnd).select(['temperature_2m'])
    );
    if (!dayPick.col) {
      console.log('2025-06-24: 0 images after trying all datasets.');
      console.log('C1');
      return;
    }

    // Junes 2020-2024
    const histPick = pickWithData(candidates, (c) =>
      c.filterDate(histStart, histEnd)
       .filter(ee.Filter.calendarRange(6, 6, 'month'))
       .select(['temperature_2m'])
    );
    if (!histPick.col) {
      console.log('2020-2024 June: 0 images after trying all datasets.');
      console.log('C1');
      return;
    }

    // 3. Processing
    const dayImg = dayPick.col.max(); // daily max (max of hourly)
    const histMaxImg = histPick.col.max(); // overall max (max of hourly across all Junes 2020-2024)

    // Pixel counts to detect C2
    const dayCount = ee.Number(
      dayImg.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: scale,
        maxPixels: 1e9
      }).get('temperature_2m')
    ).getInfo();

    const histCount = ee.Number(
      histMaxImg.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: scale,
        maxPixels: 1e9
      }).get('temperature_2m')
    ).getInfo();

    if (!dayCount || dayCount === 0 || !histCount || histCount === 0) {
      console.log(`Valid pixels - Day: ${dayCount || 0}, Hist: ${histCount || 0}`);
      console.log('C2');
      return;
    }

    // 4. Calculation
    const dayValK = ee.Number(
      dayImg.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: roi,
        scale: scale,
        maxPixels: 1e9
      }).get('temperature_2m')
    ).getInfo();

    const histValK = ee.Number(
      histMaxImg.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: roi,
        scale: scale,
        maxPixels: 1e9
      }).get('temperature_2m')
    ).getInfo();

    // 5. Validation & Final Answer
    function validTempK(v) { return v !== null && v !== undefined && isFinite(v) && v > 180 && v < 350; }

    if (!validTempK(dayValK) || !validTempK(histValK)) {
      console.log(`Invalid values - DayK: ${dayValK}, HistK: ${histValK}`);
      console.log('C3');
      return;
    }

    const dayValC = dayValK - 273.15;
    const histValC = histValK - 273.15;

    console.log(`Dataset (Day): ${dayPick.id}`);
    console.log(`Dataset (Hist): ${histPick.id}`);
    console.log(`2025-06-24 hourly imgs: ${dayPick.size}; daily max: ${dayValK.toFixed(2)} K (${dayValC.toFixed(2)} °C); pixels: ${dayCount}`);
    console.log(`2020-2024 June hourly imgs: ${histPick.size}; overall max: ${histValK.toFixed(2)} K (${histValC.toFixed(2)} °C); pixels: ${histCount}`);

    const isHigher = dayValK > histValK;
    console.log(`Comparison: 2025-06-24 > any June 2020-2024? ${isHigher ? 'Yes' : 'No'}`);

    console.log(isHigher ? 'A' : 'B');
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
